CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN CREATE TYPE card_status AS ENUM ('unassigned','active','suspended'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE app_role AS ENUM ('customer','admin'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS profiles(id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,full_name text,email text,role app_role NOT NULL DEFAULT 'customer',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS batches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),label text NOT NULL,card_count int NOT NULL CHECK(card_count>0),created_by uuid REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cards(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),card_code text UNIQUE NOT NULL,status card_status NOT NULL DEFAULT 'unassigned',batch_id uuid REFERENCES batches(id) ON DELETE SET NULL,scan_count bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS businesses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),card_id uuid UNIQUE NOT NULL REFERENCES cards(id),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,business_name text NOT NULL,target_url text NOT NULL,category text,address text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS businesses_user_id_idx ON businesses(user_id); CREATE INDEX IF NOT EXISTS cards_code_idx ON cards(card_code);
CREATE OR REPLACE FUNCTION handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name,email) VALUES(NEW.id,NEW.raw_user_meta_data->>'full_name',NEW.email) ON CONFLICT(id) DO NOTHING; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users; CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION handle_new_user();
CREATE OR REPLACE FUNCTION is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM profiles WHERE id=auth.uid() AND role='admin') $$;
CREATE OR REPLACE FUNCTION get_card_redirect(p_card_code text) RETURNS TABLE(target_url text) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE cards SET scan_count=scan_count+1 WHERE card_code=p_card_code AND status='active'; RETURN QUERY SELECT b.target_url FROM cards c JOIN businesses b ON b.card_id=c.id WHERE c.card_code=p_card_code AND c.status='active'; END $$;
CREATE OR REPLACE FUNCTION activate_card(p_card_code text,p_business_name text,p_target_url text,p_category text) RETURNS SETOF businesses LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c cards; r businesses; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF; SELECT * INTO c FROM cards WHERE card_code=p_card_code FOR UPDATE; IF c.id IS NULL OR c.status <> 'unassigned' THEN RAISE EXCEPTION 'card unavailable'; END IF; INSERT INTO businesses(card_id,user_id,business_name,target_url,category) VALUES(c.id,auth.uid(),p_business_name,p_target_url,p_category) RETURNING * INTO r; UPDATE cards SET status='active' WHERE id=c.id; RETURN NEXT r; END $$;
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY; ALTER TABLE batches ENABLE ROW LEVEL SECURITY; ALTER TABLE cards ENABLE ROW LEVEL SECURITY; ALTER TABLE businesses ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS profiles_self ON profiles; CREATE POLICY profiles_self ON profiles FOR SELECT USING(id=auth.uid() OR is_admin());
DROP POLICY IF EXISTS cards_owner ON cards; CREATE POLICY cards_owner ON cards FOR SELECT USING(is_admin() OR EXISTS(SELECT 1 FROM businesses b WHERE b.card_id=cards.id AND b.user_id=auth.uid()));
DROP POLICY IF EXISTS businesses_owner ON businesses; CREATE POLICY businesses_owner ON businesses FOR ALL USING(user_id=auth.uid() OR is_admin()) WITH CHECK(user_id=auth.uid() OR is_admin());
DROP POLICY IF EXISTS batches_admin ON batches; CREATE POLICY batches_admin ON batches FOR ALL USING(is_admin()) WITH CHECK(is_admin());
GRANT EXECUTE ON FUNCTION get_card_redirect(text) TO anon,authenticated; GRANT EXECUTE ON FUNCTION activate_card(text,text,text,text) TO authenticated;
